import { Plus } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Input, Select } from '@/components/ui/form';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { ROLES } from '@/lib/authorization';
import { User } from '@/types/api';
import { downloadCsv, toCsv } from '@/utils/csv';
import { formatDate } from '@/utils/format';

import { useUsers } from '../api/get-users';

import { DeleteUser } from './delete-user';

type RoleFilter = 'ALL' | User['role'];

const roleOptions = [
  { label: 'All roles', value: 'ALL' },
  { label: 'Admin', value: ROLES.ADMIN },
  { label: 'User', value: ROLES.USER },
];

const filterUsers = (users: User[], role: RoleFilter, search: string) => {
  const query = search.trim().toLowerCase();

  return users.filter((user) => {
    if (role !== 'ALL' && user.role !== role) return false;

    if (!query) return true;

    return [`${user.firstName} ${user.lastName}`, user.email].some((value) =>
      value.toLowerCase().includes(query),
    );
  });
};

const exportUsers = (users: User[]) => {
  const rows = users.map((user) => [
    `${user.firstName} ${user.lastName}`,
    user.email,
    user.role,
    formatDate(user.createdAt),
  ]);

  downloadCsv('users.csv', toCsv([['Name', 'Email', 'Role', 'Joined'], ...rows]));
};

export const UsersList = () => {
  const usersQuery = useUsers();
  const [role, setRole] = React.useState<RoleFilter>('ALL');
  const [search, setSearch] = React.useState('');

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  const filteredUsers = filterUsers(users, role, search);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-end gap-4">
        <div className="min-w-60 flex-1">
          <Input
            type="search"
            label="Search"
            placeholder="Search by name or email"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            registration={{}}
          />
        </div>
        <div>
          <Select
            label="Role"
            options={roleOptions}
            defaultValue={role}
            registration={{
              onChange: async (event) => {
                setRole(event.target.value as RoleFilter);
              },
            }}
          />
        </div>
        <Button
          variant="outline"
          icon={<Plus className="size-4" />}
          disabled={filteredUsers.length === 0}
          onClick={() => exportUsers(filteredUsers)}
        >
          Export CSV
        </Button>
      </div>
      <Table
        data={filteredUsers}
        columns={[
          {
            title: 'First Name',
            field: 'firstName',
          },
          {
            title: 'Last Name',
            field: 'lastName',
          },
          {
            title: 'Email',
            field: 'email',
          },
          {
            title: 'Role',
            field: 'role',
          },
          {
            title: 'Created At',
            field: 'createdAt',
            Cell({ entry: { createdAt } }) {
              return <span>{formatDate(createdAt)}</span>;
            },
          },
          {
            title: '',
            field: 'id',
            Cell({ entry: { id } }) {
              return <DeleteUser id={id} />;
            },
          },
        ]}
      />
    </div>
  );
};
